package app.kinnect.live;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.*;import org.json.*;

/** Native, local-file karaoke with one consented singer at a time. */
final class LiveKaraoke {
 private YouTubeSongSearch youtube;private String youtubeReference="";
 interface Room {LiveAudioMix mix();boolean joined();boolean host();String self();JSONObject stage();void send(String type,Object...args);void toast(String text);}
 private final Activity activity;private final Room room;private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();
 private JSONObject state=new JSONObject();private JSONArray lines=new JSONArray();private String title="",pendingSinger="",trackOwner="";private boolean importing,closed,showLyrics=true,published;private long receivedAt,lastSync,serverElapsed;private int publishedRevision=-1;private Dialog controls;private TextView current,next,previous,caption,entry;private LinearLayout lyricBox;private LiveAudioMix loadedMix;
 LiveKaraoke(Activity activity,Room room){this.activity=activity;this.room=room;handler.post(tick);}
 private int dp(int v){return Math.round(v*activity.getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new KinnectText(activity);t.setText(I18n.t(s));t.setTextSize(size);t.setTextColor(0xffffffff);t.setPadding(dp(8),dp(4),dp(8),dp(4));return t;}
 private LinearLayout column(){LinearLayout l=new LinearLayout(activity);l.setOrientation(1);return l;}
 private boolean turn(){return room.self().equals(state.optString("singerId",room.self()))&&(room.host()||room.stage()!=null&&room.stage().optString("role").equals("guest"));}
 void mount(FrameLayout stage){LinearLayout card=column();card.setPadding(dp(8),dp(4),dp(8),dp(5));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xc51a1428);bg.setCornerRadius(dp(14));card.setBackground(bg);entry=text("Hát karaoke · Chọn bài",12);entry.setMinHeight(dp(44));entry.setMaxLines(2);entry.setEllipsize(android.text.TextUtils.TruncateAt.END);entry.setCompoundDrawablePadding(dp(6));android.graphics.drawable.Drawable icon=WebIcons.load(activity,"mic");icon.setTint(0xffc6b3ff);icon.setBounds(0,0,dp(20),dp(20));entry.setCompoundDrawables(icon,null,null,null);entry.setOnClickListener(v->open());card.addView(entry,new LinearLayout.LayoutParams(-1,-2));lyricBox=column();previous=text("",11);previous.setTextColor(0xffb5a9c9);current=text("Chọn nhạc nền để bắt đầu",16);current.setTypeface(null,1);next=text("",11);next.setTextColor(0xffc5b9d7);for(TextView t:new TextView[]{previous,current,next}){t.setGravity(Gravity.CENTER);t.setMaxLines(2);lyricBox.addView(t,new LinearLayout.LayoutParams(-1,-2));}card.addView(lyricBox);FrameLayout.LayoutParams at=new FrameLayout.LayoutParams(-1,-2,Gravity.TOP);at.setMargins(dp(10),dp(94),dp(10),0);stage.addView(card,at);render();}
 void state(JSONObject message){JSONObject incoming=message.optJSONObject("karaoke");if(incoming==null)return;String before=state.optString("singerId");int revision=state.optInt("revision",-1);state=incoming;receivedAt=SystemClock.elapsedRealtime();serverElapsed=state.optBoolean("playing")?Math.max(0,Math.min(600000,message.optLong("serverNow")-state.optLong("updatedAt"))):0;LiveAudioMix mix=room.mix();if(!before.isEmpty()&&!before.equals(state.optString("singerId"))||revision!=state.optInt("revision")&&published&&publishedRevision>=0&&publishedRevision!=state.optInt("revision")){if(mix!=null)mix.playing=false;published=false;publishedRevision=-1;}
  if(turn()&&mix!=null&&mix==loadedMix&&state.optString("title").equals(title)&&state.optInt("revision")>publishedRevision){published=true;publishedRevision=state.optInt("revision");}
  if(!turn()&&mix!=null)mix.playing=false;render();
 }
 void stage(){JSONObject stage=room.stage();if(!pendingSinger.isEmpty()&&stage!=null){JSONArray people=stage.optJSONArray("participants");for(int i=0;people!=null&&i<people.length();i++)if(people.optJSONObject(i).optString("id").equals(pendingSinger)){room.send("sing-select","to",pendingSinger);pendingSinger="";break;}}}
 void publish(){LiveAudioMix mix=room.mix();if(!room.joined()||!turn()||mix==null||mix!=loadedMix||mix.durationMs()<1000||importing)return;mix.playing=false;room.send("sing-track","title",title,"durationMs",mix.durationMs(),"lines",lines);published=false;publishedRevision=-1;}
 void open(){if(closed)return;if(controls!=null)controls.dismiss();LinearLayout body=column();caption=text(title.isEmpty()?"Chưa chọn nhạc nền":title,14);caption.setTextColor(WebTheme.isDark(activity)?0xfff6f1ff:0xff271f38);body.addView(caption);
  if(!room.joined()||turn()){
   action(body,"music","Chọn nhạc nền từ máy",()->pick(321,"audio/*"));action(body,"type","Nhập lời LRC có mốc thời gian",()->pick(322,"*/*"));

   action(body,"search","Tìm bài trên YouTube",()->{LiveAudioMix active=room.mix();if(active!=null&&active.playing){active.playing=false;transport();}closeSheet();if(youtube!=null)youtube.close();youtube=new YouTubeSongSearch(activity,(name,url)->{youtubeReference=name;room.toast("Đã chọn bài tham khảo. Chọn nhạc có quyền sử dụng để phát vào Live.");});youtube.show();});
   if(!youtubeReference.isEmpty()){TextView reference=text(youtubeReference,12);reference.setTextColor(0xff9877ef);reference.setMaxLines(2);body.addView(reference);}
   action(body,"pencil","Đổi tên bài hát",this::rename);
   if(room.joined()){action(body,"play",room.mix()!=null&&room.mix().playing?"Tạm dừng bài hát":"Phát / tiếp tục bài hát",()->{LiveAudioMix mix=room.mix();if(mix==null||mix!=loadedMix){room.toast("Chọn nhạc nền trước.");return;}if(!published){publish();room.toast("Đang chuẩn bị bài hát, bấm phát lại sau giây lát.");return;}mix.playing=!mix.playing;transport();open();});action(body,"rotate_ccw","Hát lại từ đầu",()->{LiveAudioMix mix=room.mix();if(mix!=null){mix.playing=false;mix.seek(0);transport();}open();});}
   LiveAudioMix mix=room.mix();if(mix!=null){slider(body,"Giọng hát",Math.round(mix.voiceGain*100),150,n->mix.voiceGain=n/100f);slider(body,"Nhạc nền",Math.round(mix.musicGain*100),100,n->mix.musicGain=n/100f);slider(body,"Độ vang",Math.round(mix.echo*100),45,n->mix.echo=n/100f);}
  }else if(!room.host()){boolean waiting=false;JSONArray queue=state.optJSONArray("queue");for(int i=0;queue!=null&&i<queue.length();i++)if(queue.optJSONObject(i).optString("id").equals(room.self()))waiting=true;final boolean cancel=waiting;action(body,"mic",waiting?"Hủy xin hát":"Xin hát",()->{room.send(cancel?"sing-cancel":"sing-request","title",title);closeSheet();});}
  if(room.host()&&room.joined())action(body,"users_round","Hàng chờ / Chuyển lượt",this::queue);
  action(body,"type",showLyrics?"Ẩn lời bài hát":"Hiện lời bài hát",()->{showLyrics=!showLyrics;render();closeSheet();});
  TextView hint=text("Dùng tai nghe để tránh vọng. Nhạc tối đa 10 phút; lời LRC hiển thị theo từng câu.",11);hint.setTextColor(WebTheme.isDark(activity)?0xffb7aec8:0xff71667e);body.addView(hint);controls=new Sheet(activity).setTitle(I18n.t("Hát karaoke")).setView(body).setNegativeButton(I18n.t("Quay lại"),null).show();
 }
 private void action(LinearLayout body,String icon,String name,Runnable click){TextView b=text(name,13);b.setTextColor(WebTheme.isDark(activity)?0xfff6f1ff:0xff271f38);b.setMinHeight(dp(48));b.setGravity(Gravity.CENTER_VERTICAL);android.graphics.drawable.Drawable d=WebIcons.load(activity,icon);d.setTint(0xff9877ef);d.setBounds(0,0,dp(22),dp(22));b.setCompoundDrawables(d,null,null,null);b.setCompoundDrawablePadding(dp(12));b.setOnClickListener(v->click.run());body.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 interface Change{void set(int n);}private void slider(LinearLayout body,String name,int initial,int max,Change changed){TextView label=text(name+" · "+initial+"%",12);label.setTextColor(WebTheme.isDark(activity)?0xffdcd2ec:0xff625674);body.addView(label);SeekBar bar=new SeekBar(activity);bar.setMax(max);bar.setProgress(initial);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff9877ef));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){if(user){changed.set(n);label.setText(I18n.t(name)+" · "+n+"%");}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});body.addView(bar,new LinearLayout.LayoutParams(-1,dp(42)));}
 private void rename(){closeSheet();EditText input=new KinnectInput(activity);input.setText(title);input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});new Sheet(activity).setTitle(I18n.t("Tên bài hát")).setView(input).setPositiveButton(I18n.t("Lưu"),(d,w)->{title=input.getText().toString().trim();publish();open();}).setNegativeButton(I18n.t("Quay lại"),(d,w)->open()).show();}
 private void queue(){closeSheet();LinearLayout body=column();action(body,"mic","Chủ phòng hát",()->{pendingSinger="";room.send("sing-select","to",room.self());closeSheet();});JSONArray q=state.optJSONArray("queue");if(q==null||q.length()==0){TextView empty=text("Chưa có người xin hát",13);empty.setTextColor(0xff8f819f);body.addView(empty);}for(int i=0;q!=null&&i<q.length();i++){JSONObject user=q.optJSONObject(i);String id=user.optString("id");boolean onStage=false;JSONArray people=room.stage()==null?null:room.stage().optJSONArray("participants");for(int n=0;people!=null&&n<people.length();n++)if(people.optJSONObject(n).optString("id").equals(id))onStage=true;final boolean ready=onStage;String name=user.optString("name")+" · "+I18n.t(ready?"Chuyển lượt":"Mời lên mic");action(body,"user_plus",name,()->{if(ready)room.send("sing-select","to",id);else{pendingSinger=id;room.send("live-guest-invite","to",id);}closeSheet();});action(body,"x",I18n.t("Bỏ khỏi hàng chờ")+" · "+user.optString("name"),()->{room.send("sing-remove","to",id);queue();});}controls=new Sheet(activity).setTitle(I18n.t("Hàng chờ hát")).setView(body).setNegativeButton(I18n.t("Quay lại"),(d,w)->open()).show();}
 private void closeSheet(){if(controls!=null){controls.dismiss();controls=null;}}
 private void pick(int code,String type){if(importing){room.toast("Đang đọc nhạc nền…");return;}closeSheet();if(code==322&&(room.mix()==null||room.mix().durationMs()==0)){room.toast("Chọn nhạc nền trước.");return;}Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{activity.startActivityForResult(intent,code);}catch(Exception e){room.toast("Không mở được thư viện tệp.");}}
 void result(int code,int result,Intent data){if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();LiveAudioMix mix=room.mix();if(mix==null){room.toast("Micro chưa sẵn sàng.");return;}importing=true;room.toast("Đang đọc nhạc nền…");io.execute(()->{String error=null;String filename="Karaoke";JSONArray parsed=null;try{if(code==321){mix.load(activity,uri);try(android.database.Cursor c=activity.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())filename=c.getString(0).replaceFirst("\\.[^.]+$","");}}else{try(InputStream in=activity.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[4096];for(int n;(n=in.read(bytes))!=-1;){if(out.size()+n>65536)throw new IOException("large");out.write(bytes,0,n);}parsed=KaraokeLyrics.parse(new String(out.toByteArray(),"UTF-8"),mix.durationMs());if(parsed.length()==0)throw new IOException("LRC");}}}catch(Exception e){error=code==321?"Không đọc được nhạc. Chọn tệp âm thanh từ 1 giây đến 10 phút.":"Lời chưa đúng định dạng LRC hoặc quá dài.";}final String failure=error,name=filename;final JSONArray resultLines=parsed;handler.post(()->{importing=false;if(closed)return;if(failure!=null){room.toast(failure);return;}if(code==321){title=name.length()>80?name.substring(0,80):name;lines=new JSONArray();loadedMix=mix;mix.monitor(true);}else lines=resultLines;publish();room.toast("Đã sẵn sàng. Mở Karaoke để phát bài.");open();});});}
 private void transport(){LiveAudioMix mix=room.mix();if(room.joined()&&turn()&&mix!=null&&publishedRevision>=0)room.send("sing-transport","revision",publishedRevision,"positionMs",mix.positionMs(),"playing",mix.playing);lastSync=SystemClock.elapsedRealtime();}
 private final Runnable tick=new Runnable(){public void run(){if(closed)return;LiveAudioMix mix=room.mix();if(room.joined()&&turn()&&mix!=null&&published&&SystemClock.elapsedRealtime()-lastSync>3000)transport();render();handler.postDelayed(this,200);}};
 private void render(){if(entry==null)return;String song=state.optString("title");entry.setText(I18n.t("Hát karaoke")+" · "+(song.isEmpty()?I18n.t(room.host()?"Chọn bài":"Xin hát"):song));lyricBox.setVisibility(showLyrics?View.VISIBLE:View.GONE);JSONArray lyric=state.optJSONArray("lines");long ms=state.optLong("positionMs")+(state.optBoolean("playing")?SystemClock.elapsedRealtime()-receivedAt+serverElapsed:0);if(turn()&&room.mix()!=null&&published)ms=room.mix().positionMs();int ix=lyric==null?-1:KaraokeLyrics.current(lyric,ms);if(lyric==null||lyric.length()==0){previous.setText(state.optString("singerName"));current.setText(I18n.t(song.isEmpty()?"Chọn nhạc nền để bắt đầu":"Bài hát chưa có lời LRC"));next.setText(I18n.t("Chạm thanh Karaoke để mở điều khiển"));}else{previous.setText(ix>0?lyric.optJSONObject(ix-1).optString("text"):"");current.setText(ix>=0?lyric.optJSONObject(ix).optString("text"):I18n.t("Chuẩn bị hát…"));next.setText(ix+1<lyric.length()?lyric.optJSONObject(ix+1).optString("text"):"");}}
 void close(){closed=true;if(youtube!=null)youtube.close();handler.removeCallbacksAndMessages(null);io.shutdownNow();closeSheet();LiveAudioMix mix=room.mix();if(mix!=null){mix.playing=false;mix.monitor(false);}}
 void pause(){if(youtube!=null)youtube.close();}
}
